modules.speeddial:
.p-speeddial {
    position: static;
    display: flex;
    gap: dt('speeddial.gap');
}

.p-speeddial-button {
    z-index: 1;
}

.p-speeddial-button.p-speeddial-rotate {
    transition:
        transform 250ms cubic-bezier(0.4, 0, 0.2, 1) 0ms,
        background dt('speeddial.transition.duration'),
        color dt('speeddial.transition.duration'),
        border-color dt('speeddial.transition.duration'),
        box-shadow dt('speeddial.transition.duration'),
        outline-color dt('speeddial.transition.duration');
    will-change: transform;
}

.p-speeddial-list {
    margin: 0;
    padding: 0;
    list-style: none;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: inset-block-start 0s linear dt('speeddial.transition.duration');
    pointer-events: none;
    outline: 0 none;
    z-index: 2;
    gap: dt('speeddial.gap');
}

.p-speeddial-item {
    transform: scale(0);
    opacity: 0;
    transition:
        transform 200ms cubic-bezier(0.4, 0, 0.2, 1) 0ms,
        opacity 0.8s;
    will-change: transform;
}

.p-speeddial-circle .p-speeddial-item,
.p-speeddial-semi-circle .p-speeddial-item,
.p-speeddial-quarter-circle .p-speeddial-item {
    position: absolute;
}

.p-speeddial-mask {
    position: absolute;
    border-radius: dt('content.border.radius');
}

.p-speeddial-open .p-speeddial-list {
    pointer-events: auto;
}

.p-speeddial-open .p-speeddial-item {
    transform: scale(1);
    opacity: 1;
}

.p-speeddial-open .p-speeddial-rotate {
    transform: rotate(45deg);
}

modules.base:
*,
::before,
::after {
    box-sizing: border-box;
}

.p-collapsible-enter-active {
    animation: p-animate-collapsible-expand 0.2s ease-out;
    overflow: hidden;
}

.p-collapsible-leave-active {
    animation: p-animate-collapsible-collapse 0.2s ease-out;
    overflow: hidden;
}

@keyframes p-animate-collapsible-expand {
    from {
        grid-template-rows: 0fr;
    }
    to {
        grid-template-rows: 1fr;
    }
}

@keyframes p-animate-collapsible-collapse {
    from {
        grid-template-rows: 1fr;
    }
    to {
        grid-template-rows: 0fr;
    }
}

.p-disabled,
.p-disabled * {
    cursor: default;
    pointer-events: none;
    user-select: none;
}

.p-disabled,
.p-component:disabled {
    opacity: dt('disabled.opacity');
}

.pi {
    font-size: dt('icon.size');
}

.p-icon {
    width: dt('icon.size');
    height: dt('icon.size');
}

.p-overlay-mask {
    background: var(--px-mask-background, dt('mask.background'));
    color: dt('mask.color');
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
}

.p-overlay-mask-enter-active {
    animation: p-animate-overlay-mask-enter dt('mask.transition.duration') forwards;
}

.p-overlay-mask-leave-active {
    animation: p-animate-overlay-mask-leave dt('mask.transition.duration') forwards;
}

@keyframes p-animate-overlay-mask-enter {
    from {
        background: transparent;
    }
    to {
        background: var(--px-mask-background, dt('mask.background'));
    }
}
@keyframes p-animate-overlay-mask-leave {
    from {
        background: var(--px-mask-background, dt('mask.background'));
    }
    to {
        background: transparent;
    }
}

.p-anchored-overlay-enter-active {
    animation: p-animate-anchored-overlay-enter 300ms cubic-bezier(.19,1,.22,1);
}

.p-anchored-overlay-leave-active {
